style.css:
@-moz-document domain("roblox.com") {
/* Target thumbnails/game images */
    .game-card-thumb,
    .thumbnail-2d,
    .game-card-thumb-container img,
    .thumbnail-2d-container img {
        position: relative !important;
        filter: brightness(1.05) sepia(0.3) hue-rotate(-30deg) saturate(2) !important;
    }

    /* Optional: add a semi-transparent pink overlay */
    .game-card-thumb::after,
    .thumbnail-2d::after,
    .thumbnail-2d-container::after {
        content: "" !important;
        position: absolute !important;
        top: 0; left: 0; right: 0; bottom: 0;
        background: rgba(255, 182, 193, 0.35) !important; /* light pink glow */
        pointer-events: none !important;
        border-radius: inherit;
    }
}
